   1: #!/usr/bin/env node
   2: // ============================================================
   3: // Claude Code Replica — CLI Entry Point
   4: // ============================================================
   5: 
   6: import * as fs from "node:fs";
   7: import * as path from "node:path";
   8: import * as crypto from "node:crypto";
   9: import * as readline from "node:readline";
  10: import dotenv from "dotenv";
  11: 
  12: import { agentLoop } from "./agent-loop.js";
  13: import { buildSystemPrompt } from "./system-prompt.js";
  14: import { ToolRegistry } from "./tool-registry.js";
  15: import { CORE_TOOLS } from "./tools.js";
  16: import { MCPManager, discoverMCPConfigs } from "./mcp.js";
  17: import { createModelCaller, resolveProviderConfig } from "./llm-adapter.js";
  18: import { PersistenceManager } from "./persistence.js";
  19: import type { Message, ModelConfig, Tool } from "./types.js";
  20: 
  21: // Load environment variables
  22: dotenv.config();
  23: 
  24: // --- Configuration ---
  25: 
  26: function loadConfig(): ModelConfig {
  27:   const provider = (process.env.LLM_PROVIDER || "openai") as ModelConfig["provider"];
  28:   const apiKey = process.env.LLM_API_KEY;
  29: 
  30:   if (!apiKey) {
  31:     console.error(
  32:       "Error: LLM_API_KEY is not set. Create a .env file or set the environment variable.",
  33:     );
  34:     process.exit(1);
  35:   }
  36: 
  37:   return resolveProviderConfig({
  38:     provider,
  39:     apiKey,
  40:     model: process.env.LLM_MODEL || undefined,
  41:     baseURL: process.env.LLM_BASE_URL || undefined,
  42:     maxTokens: process.env.LLM_MAX_TOKENS
  43:       ? parseInt(process.env.LLM_MAX_TOKENS)
  44:       : undefined,
  45:     temperature: process.env.LLM_TEMPERATURE
  46:       ? parseFloat(process.env.LLM_TEMPERATURE)
  47:       : undefined,
  48:   });
  49: }
  50: 
  51: // --- Workspace ---
  52: 
  53: function getWorkspaceRoot(): string {
  54:   return process.env.WORKSPACE_ROOT || process.cwd();
  55: }
  56: 
  57: // --- Load CLAUDE.md ---
  58: 
  59: function loadClaudeMd(workspaceRoot: string): string | undefined {
  60:   const claudeMdPath = path.join(workspaceRoot, "CLAUDE.md");
  61:   try {
  62:     return fs.readFileSync(claudeMdPath, "utf-8");
  63:   } catch {
  64:     return undefined;
  65:   }
  66: }
  67: 
  68: // --- Main ---
  69: 
  70: async function main() {
  71:   console.log("╔══════════════════════════════════════╗");
  72:   console.log("║   Claude Code Replica — v1.0.0      ║");
  73:   console.log("║   Local AI Coding Assistant         ║");
  74:   console.log("╚══════════════════════════════════════╝");
  75:   console.log("");
  76: 
  77:   // Load configuration
  78:   const modelConfig = loadConfig();
  79:   const workspaceRoot = getWorkspaceRoot();
  80:   const claudeMdContent = loadClaudeMd(workspaceRoot);
  81: 
  82:   console.log(`Provider: ${modelConfig.provider}`);
  83:   console.log(`Model:    ${modelConfig.model}`);
  84:   console.log(`Workspace: ${workspaceRoot}`);
  85:   console.log("");
  86: 
  87:   // --- Persistence ---
  88: 
  89:   const messages: Message[] = [];
  90:   const persistence = new PersistenceManager(workspaceRoot);
  91: 
  92:   // Parse --session from CLI args
  93:   const sessionArg = process.argv.find((a) => a.startsWith("--session="));
  94:   let sessionId = sessionArg?.split("=")[1];
  95: 
  96:   // If no session specified, list available ones
  97:   if (!sessionId) {
  98:     const sessions = await persistence.listSessions();
  99:     const incomplete = sessions.filter((s) => !s.completed);
 100:     if (incomplete.length > 0) {
 101:       console.log("Recent incomplete sessions:");
 102:       for (const s of incomplete.slice(0, 5)) {
 103:         console.log(
 104:           `  ${s.sessionId.slice(0, 8)}... — ${s.messageCount} msgs — ${new Date(s.updatedAt).toLocaleString()}`,
 105:         );
 106:       }
 107:       console.log(
 108:         '  Use --session=<id> to resume, or continue for a new session.',
 109:       );
 110:       console.log("");
 111:     }
 112:   }
 113: 
 114:   // Generate or resume session
 115:   if (sessionId) {
 116:     const existing = await persistence.load(sessionId);
 117:     if (existing) {
 118:       messages.push(...existing.messages);
 119:       console.log(
 120:         `Resumed session ${sessionId.slice(0, 8)}... (${existing.messageCount} messages)`,
 121:       );
 122:     } else {
 123:       console.log(
 124:         `Session ${sessionId.slice(0, 8)}... not found. Starting new session.`,
 125:       );
 126:       sessionId = persistence.generateId();
 127:     }
 128:   } else {
 129:     sessionId = persistence.generateId();
 130:   }
 131:   console.log(`Session: ${sessionId.slice(0, 8)}...`);
 132:   console.log("");
 133: 
 134:   // --- Tool Setup ---
 135: 
 136:   const toolRegistry = new ToolRegistry();
 137:   for (const tool of CORE_TOOLS) {
 138:     toolRegistry.register(tool);
 139:   }
 140: 
 141:   // MCP Setup
 142:   const mcpManager = new MCPManager();
 143:   const mcpConfigs = discoverMCPConfigs(workspaceRoot);
 144:   for (const configPath of mcpConfigs) {
 145:     await mcpManager.loadConfig(configPath);
 146:   }
 147:   for (const mcpTool of mcpManager.getAllTools()) {
 148:     toolRegistry.register(mcpTool);
 149:   }
 150: 
 151:   console.log(`Tools loaded: ${toolRegistry.enabledCount}`);
 152:   if (mcpManager.serverCount > 0) {
 153:     console.log(`MCP servers:  ${mcpManager.serverCount}`);
 154:   }
 155:   console.log("");
 156: 
 157:   // --- System Prompt ---
 158: 
 159:   const systemPrompt = buildSystemPrompt({
 160:     workspaceRoot,
 161:     tools: toolRegistry.getEnabledTools(),
 162:     claudeMdContent,
 163:   });
 164: 
 165:   // --- Model Caller ---
 166: 
 167:   const callModel = createModelCaller(modelConfig);
 168: 
 169:   // --- Conversation ---
 170: 
 171:   const tools = toolRegistry.getEnabledTools();
 172: 
 173:   // --- REPL ---
 174: 
 175:   const rl = readline.createInterface({
 176:     input: process.stdin,
 177:     output: process.stdout,
 178:   });
 179: 
 180:   const askQuestion = (prompt: string): Promise<string> => {
 181:     return new Promise((resolve) => {
 182:       rl.question(prompt, (answer) => {
 183:         resolve(answer);
 184:       });
 185:     });
 186:   };
 187: 
 188:   console.log('Type your request (or "exit" to quit):\n');
 189: 
 190:   // eslint-disable-next-line no-constant-condition
 191:   while (true) {
 192:     const userInput = await askQuestion("\n> ");
 193: 
 194:     if (!userInput.trim()) continue;
 195:     if (userInput.toLowerCase() === "exit") break;
 196: 
 197:     // Add user message
 198:     messages.push({
 199:       role: "user",
 200:       content: [{ type: "text", text: userInput }],
 201:     });
 202: 
 203:     // Run agent loop
 204:     const loop = agentLoop(
 205:       messages,
 206:       tools,
 207:       callModel,
 208:       modelConfig,
 209:       {
 210:         systemPrompt,
 211:         maxTurns: 50,
 212:       },
 213:     );
 214: 
 215:     let lastText = "";
 216: 
 217:     for await (const event of loop) {
 218:       switch (event.type) {
 219:         case "text_delta":
 220:           process.stdout.write(event.delta);
 221:           lastText += event.delta;
 222:           break;
 223: 
 224:         case "tool_use":
 225:           console.log(`\n  🔧 Using tool: ${event.name}`);
 226:           break;
 227: 
 228:         case "tool_results":
 229:           for (const result of event.results) {
 230:             if (result.error) {
 231:               console.log(`  ❌ ${result.toolName}: ${result.error}`);
 232:             } else {
 233:               const preview = result.formatted.slice(0, 200);
 234:               console.log(`  ✅ ${result.toolName}: ${preview}...`);
 235:             }
 236:           }
 237:           // Auto-save after tool execution
 238:           persistence.save(sessionId!, messages).catch(() => {});
 239:           break;
 240: 
 241:         case "compacting":
 242:           console.log("\n  📦 Compacting context...");
 243:           break;
 244: 
 245:         case "usage":
 246:           // Silent
 247:           break;
 248: 
 249:         case "error":
 250:           console.error(`\n  ⚠️ Error:`, event.error);
 251:           break;
 252: 
 253:         case "done":
 254:           // Final assistant text was added to messages in the loop
 255:           persistence.save(sessionId!, messages).catch(() => {});
 256:           break;
 257: 
 258:         case "aborted":
 259:           console.log(`\n  ⏹️ Aborted: ${event.reason}`);
 260:           break;
 261:       }
 262:     }
 263: 
 264:     console.log(""); // New line after response
 265:   }
 266: 
 267:   // Cleanup
 268:   rl.close();
 269:   await persistence.save(sessionId!, messages, { completed: true });
 270:   await mcpManager.disconnectAll();
 271:   console.log("\nGoodbye!");
 272: }
 273: 
 274: main().catch((error) => {
 275:   console.error("Fatal error:", error);
 276:   process.exit(1);
 277: });
