   1: // ============================================================
   2: // Agent Loop — The heart of the system
   3: // ============================================================
   4: 
   5: import type {
   6:   LoopEvent,
   7:   LoopOptions,
   8:   Message,
   9:   ModelCaller,
  10:   ModelConfig,
  11:   Tool,
  12:   ToolCall,
  13:   ToolExecutionResult,
  14: } from "./types.js";
  15: 
  16: // --- Agent Loop (Async Generator) ---
  17: 
  18: export async function* agentLoop(
  19:   messages: Message[],
  20:   tools: Tool[],
  21:   callModel: ModelCaller,
  22:   modelConfig: ModelConfig,
  23:   options: LoopOptions,
  24: ): AsyncGenerator<LoopEvent> {
  25:   const {
  26:     maxTurns = 50,
  27:     autoCompactThreshold = 150_000,
  28:     systemPrompt,
  29:     abortSignal,
  30:   } = options;
  31: 
  32:   let turnCount = 0;
  33:   let totalTokens = 0;
  34: 
  35:   while (turnCount < maxTurns) {
  36:     // Check for abort
  37:     if (abortSignal?.aborted) {
  38:       yield { type: "aborted", reason: abortSignal.reason };
  39:       return;
  40:     }
  41: 
  42:     // === STEP 1: Check if compaction is needed ===
  43:     if (estimateTokens(messages) > autoCompactThreshold) {
  44:       yield { type: "compacting" };
  45:       messages = await autoCompact(messages, callModel, modelConfig);
  46:       yield { type: "compacted", summary: "Context compressed" };
  47:     }
  48: 
  49:     // === STEP 2: Call the LLM ===
  50:     yield { type: "thinking" };
  51: 
  52:     let textBuffer = "";
  53:     const toolCalls: ToolCall[] = [];
  54:     let usage: { input_tokens: number; output_tokens: number } | null = null;
  55: 
  56:     try {
  57:       for await (const event of callModel(
  58:         messages,
  59:         tools,
  60:         systemPrompt,
  61:         modelConfig,
  62:       )) {
  63:         switch (event.type) {
  64:           case "text_delta":
  65:             textBuffer += event.delta;
  66:             yield { type: "text_delta", delta: event.delta };
  67:             break;
  68: 
  69:           case "tool_use":
  70:             toolCalls.push({
  71:               id: event.id,
  72:               type: "function",
  73:               function: {
  74:                 name: event.name,
  75:                 arguments: JSON.stringify(event.input),
  76:               },
  77:             });
  78:             yield {
  79:               type: "tool_use",
  80:               name: event.name,
  81:               input: event.input,
  82:             };
  83:             break;
  84: 
  85:           case "done":
  86:             usage = event.usage;
  87:             totalTokens += usage.input_tokens + usage.output_tokens;
  88:             yield { type: "usage", usage };
  89:             break;
  90: 
  91:           case "error":
  92:             // Handle recoverable errors
  93:             const recovery = await handleModelError(
  94:               event.error,
  95:               messages,
  96:               callModel,
  97:               modelConfig,
  98:             );
  99:             if (recovery === "retry") continue;
 100:             if (recovery === "abort") {
 101:               yield { type: "error", error: event.error };
 102:               return;
 103:             }
 104:             break;
 105:         }
 106:       }
 107:     } catch (error) {
 108:       yield { type: "error", error };
 109:       return;
 110:     }
 111: 
 112:     // === STEP 3: If no tool calls, we're done ===
 113:     if (toolCalls.length === 0) {
 114:       // Save the assistant's text response to message history
 115:       if (textBuffer) {
 116:         messages.push({
 117:           role: "assistant",
 118:           content: textBuffer,
 119:         });
 120:       }
 121:       yield {
 122:         type: "done",
 123:         finishReason: "end_turn",
 124:         turns: turnCount,
 125:       };
 126:       return;
 127:     }
 128: 
 129:     // === STEP 4: Add assistant message to history ===
 130:     messages.push({
 131:       role: "assistant",
 132:       content: textBuffer || null,
 133:       tool_calls: toolCalls,
 134:     });
 135: 
 136:     // === STEP 5: Execute tool calls (parallel for safe ones) ===
 137:     const toolResults = await executeToolCalls(toolCalls, tools, modelConfig);
 138: 
 139:     // === STEP 6: Add tool results to history ===
 140:     for (let i = 0; i < toolCalls.length; i++) {
 141:       messages.push({
 142:         role: "tool",
 143:         tool_call_id: toolCalls[i].id,
 144:         name: toolCalls[i].function.name,
 145:         content: toolResults[i].formatted,
 146:       });
 147:     }
 148: 
 149:     yield { type: "tool_results", results: toolResults };
 150: 
 151:     turnCount++;
 152:   }
 153: 
 154:   // Max turns reached
 155:   yield {
 156:     type: "done",
 157:     finishReason: "max_turns",
 158:     turns: turnCount,
 159:     message: "Maximum turns reached. Continue?",
 160:   };
 161: }
 162: 
 163: // --- Tool Call Execution ---
 164: 
 165: async function executeToolCalls(
 166:   toolCalls: ToolCall[],
 167:   tools: Tool[],
 168:   modelConfig: ModelConfig,
 169: ): Promise<ToolExecutionResult[]> {
 170:   // Separate into parallel-safe and serial groups
 171:   const parallelCalls: ToolCall[] = [];
 172:   const serialCalls: ToolCall[] = [];
 173: 
 174:   for (const call of toolCalls) {
 175:     const tool = tools.find((t) => t.name === call.function.name);
 176:     if (!tool) {
 177:       serialCalls.push(call);
 178:       continue;
 179:     }
 180:     if (tool.isConcurrencySafe()) {
 181:       parallelCalls.push(call);
 182:     } else {
 183:       serialCalls.push(call);
 184:     }
 185:   }
 186: 
 187:   const results: ToolExecutionResult[] = [];
 188: 
 189:   // Execute parallel-safe calls simultaneously
 190:   if (parallelCalls.length > 0) {
 191:     const parallelResults = await Promise.all(
 192:       parallelCalls.map((call) => executeSingleTool(call, tools, modelConfig)),
 193:     );
 194:     results.push(...parallelResults);
 195:   }
 196: 
 197:   // Execute serial calls one at a time
 198:   for (const call of serialCalls) {
 199:     const result = await executeSingleTool(call, tools, modelConfig);
 200:     results.push(result);
 201:   }
 202: 
 203:   return results;
 204: }
 205: 
 206: async function executeSingleTool(
 207:   toolCall: ToolCall,
 208:   tools: Tool[],
 209:   modelConfig: ModelConfig,
 210: ): Promise<ToolExecutionResult> {
 211:   const tool = tools.find((t) => t.name === toolCall.function.name);
 212: 
 213:   if (!tool) {
 214:     return {
 215:       toolName: toolCall.function.name,
 216:       error: `Unknown tool: ${toolCall.function.name}`,
 217:       formatted: `Error: Tool "${toolCall.function.name}" is not available.`,
 218:     };
 219:   }
 220: 
 221:   try {
 222:     let input: Record<string, unknown>;
 223:     try {
 224:       input = JSON.parse(toolCall.function.arguments);
 225:     } catch {
 226:       return {
 227:         toolName: tool.name,
 228:         error: "Invalid JSON arguments",
 229:         formatted: `Error: Failed to parse arguments for ${tool.name}`,
 230:       };
 231:     }
 232: 
 233:     const startTime = Date.now();
 234:     const result = await tool.call(input, {
 235:       workspaceRoot: process.cwd(),
 236:       sessionId: "default",
 237:       permissionMode: "default",
 238:       modelConfig,
 239:     });
 240:     const duration = Date.now() - startTime;
 241: 
 242:     return {
 243:       toolName: tool.name,
 244:       result,
 245:       formatted: tool.formatResult({
 246:         ...result,
 247:         metadata: { ...result.metadata, durationMs: duration },
 248:       }),
 249:       durationMs: duration,
 250:     };
 251:   } catch (error) {
 252:     const message = error instanceof Error ? error.message : String(error);
 253:     return {
 254:       toolName: tool.name,
 255:       error: message,
 256:       formatted: `Error executing ${tool.name}: ${message}`,
 257:     };
 258:   }
 259: }
 260: 
 261: // --- Token Estimation (Simple Heuristic) ---
 262: 
 263: function estimateTokens(messages: Message[]): number {
 264:   let total = 0;
 265:   for (const msg of messages) {
 266:     switch (msg.role) {
 267:       case "user":
 268:         for (const block of msg.content) {
 269:           if (block.type === "text") total += block.text.length;
 270:         }
 271:         break;
 272:       case "assistant":
 273:         if (msg.content) total += msg.content.length;
 274:         if (msg.tool_calls) {
 275:           for (const tc of msg.tool_calls) {
 276:             total += tc.function.arguments.length + tc.function.name.length;
 277:           }
 278:         }
 279:         break;
 280:       case "tool":
 281:         total += msg.content.length;
 282:         break;
 283:       case "system":
 284:         total += msg.content.length;
 285:         break;
 286:     }
 287:   }
 288:   // Rough estimate: ~1 token per 4 characters
 289:   return Math.ceil(total / 4);
 290: }
 291: 
 292: // --- Auto-Compaction ---
 293: 
 294: async function autoCompact(
 295:   messages: Message[],
 296:   callModel: ModelCaller,
 297:   modelConfig: ModelConfig,
 298: ): Promise<Message[]> {
 299:   const TAIL_SIZE = 20;
 300:   const oldMessages = messages.slice(0, -TAIL_SIZE);
 301:   const tailMessages = messages.slice(-TAIL_SIZE);
 302: 
 303:   if (oldMessages.length === 0) return messages;
 304: 
 305:   // Summarize old messages
 306:   const summaryPrompt = `Summarize the conversation so far. Include:
 307: 1. What the user asked for (the main task)
 308: 2. Key decisions made
 309: 3. Files that were modified (with paths)
 310: 4. What still needs to be done
 311: 5. Any important context for continuing the work
 312: 
 313: Be concise but complete. This summary will replace the old messages
 314: so the conversation can continue with a fresh context window.`;
 315: 
 316:   const summaryMessages: Message[] = [
 317:     ...oldMessages,
 318:     { role: "user", content: [{ type: "text", text: summaryPrompt }] },
 319:   ];
 320: 
 321:   // Call model without tools for summarization
 322:   const chunks: string[] = [];
 323:   for await (const event of callModel(
 324:     summaryMessages,
 325:     [],
 326:     "You are a helpful assistant that summarizes conversations.",
 327:     modelConfig,
 328:   )) {
 329:     if (event.type === "text_delta") {
 330:       chunks.push(event.delta);
 331:     }
 332:   }
 333:   const summary = chunks.join("");
 334: 
 335:   // Rebuild: system summary + tail
 336:   return [
 337:     {
 338:       role: "system",
 339:       content: `[CONVERSATION SUMMARY]\n${summary}`,
 340:     },
 341:     ...tailMessages,
 342:   ];
 343: }
 344: 
 345: // --- Error Recovery ---
 346: 
 347: async function handleModelError(
 348:   error: unknown,
 349:   _messages: Message[],
 350:   _callModel: ModelCaller,
 351:   _modelConfig: ModelConfig,
 352: ): Promise<"retry" | "abort"> {
 353:   const err = error as any;
 354: 
 355:   // Rate limit → wait and retry
 356:   if (err?.status === 429) {
 357:     const delay = err?.retryAfter || 5000;
 358:     await sleep(delay);
 359:     return "retry";
 360:   }
 361: 
 362:   // Context too long → compact and retry
 363:   if (
 364:     err?.status === 400 &&
 365:     (err?.message?.includes("context_length") ||
 366:       err?.message?.includes("maximum context"))
 367:   ) {
 368:     return "retry";
 369:   }
 370: 
 371:   // Auth error → abort
 372:   if (err?.status === 401 || err?.status === 403) {
 373:     return "abort";
 374:   }
 375: 
 376:   // Unknown error → abort
 377:   return "abort";
 378: }
 379: 
 380: function sleep(ms: number): Promise<void> {
 381:   return new Promise((resolve) => setTimeout(resolve, ms));
 382: }
