  68: export const ReadTool: Tool = createTool<ReadInput>({
  69:   name: "read",
  70:   description: "Read a file from the local filesystem",
  71:   promptDescription:
  72:     "Read a file from the local filesystem. Returns file content with line numbers.",
  73:   inputSchema: {
  74:     type: "object",
  75:     properties: {
  76:       filePath: {
  77:         type: "string",
  78:         description: "The absolute path to the file to read",
  79:       },
  80:       offset: {
  81:         type: "number",
  82:         description: "Line number to start reading from (1-based)",
  83:       },
  84:       limit: {
  85:         type: "number",
  86:         description: "Maximum number of lines to read",
  87:       },
  88:     },
  89:     required: ["filePath"],
  90:   },
  91:   isReadOnly: true,
  92:   isConcurrencySafe: true,
  93: 
  94:   async call(input, context): Promise<ToolResult> {
  95:     const filePath = path.resolve(context.workspaceRoot, input.filePath);
  96: 
  97:     // Security: prevent directory traversal
  98:     if (!filePath.startsWith(context.workspaceRoot)) {
  99:       return {
 100:         content: "",
 101:         error: `Access denied: "${input.filePath}" is outside workspace`,
 102:       };
 103:     }
 104: 
 105:     if (isBlockedPath(filePath)) {
 106:       return {
 107:         content: "",
 108:         error: `Access denied: "${input.filePath}" is a blocked path`,
 109:       };
 110:     }
 111: 
 112:     try {
 113:       const stat = fs.statSync(filePath);
 114: 
 115:       if (stat.isDirectory()) {
 116:         return {
 117:           content: "",
 118:           error: `"${input.filePath}" is a directory, not a file`,
 119:         };
 120:       }
 121: 
 122:       // Check for binary files
 123:       const buffer = fs.readFileSync(filePath);
 124:       if (isBinary(buffer)) {
 125:         return {
 126:           content: `[Binary file: ${filePath}]`,
 127:           metadata: { fileSize: stat.size },
 128:         };
 129:       }
 130: 
 131:       let lines = buffer.toString("utf-8").split("\n");
 132:       const totalLines = lines.length;
 133: 
 134:       // Apply offset and limit
 135:       const start = (input.offset ?? 1) - 1;
 136:       const end = input.limit ? start + input.limit : Math.min(start + 2000, totalLines);
 137:       lines = lines.slice(start, end);
 138: 
 139:       // Add line numbers (4-space padded)
 140:       const numbered = lines
 141:         .map((line, i) => {
 142:           const num = String(start + i + 1).padStart(4, " ");
 143:           return `${num}: ${line}`;
 144:         })
 145:         .join("\n");
 146: 
 147:       const truncated = end < totalLines;
 148: 
 149:       return {
 150:         content: numbered,
 151:         truncated,
 152:         metadata: {
 153:           linesRead: lines.length,
 154:           fileSize: stat.size,
 155:         },
 156:       };
 157:     } catch (error: any) {
 158:       if (error.code === "ENOENT") {
 159:         return { content: "", error: `File not found: "${input.filePath}"` };
 160:       }
 161:       return {
 162:         content: "",
 163:         error: `Error reading file: ${error.message}`,
 164:       };
 165:     }
 166:   },
 167: 
 168:   async checkPermissions(_input, _context) {
 169:     return { allowed: true }; // Read-only, always allowed
 170:   },
 171: });
