 522: // ============================================================
 523: 
 524: export const GrepTool: Tool = createTool<GrepInput>({
 525:   name: "grep",
 526:   description: "Search file contents with regex",
 527:   promptDescription:
 528:     "Search file contents with regex pattern. Uses ripgrep if available, falls back to Node.js.",
 529:   inputSchema: {
 530:     type: "object",
 531:     properties: {
 532:       pattern: {
 533:         type: "string",
 534:         description: "Regex pattern to search for",
 535:       },
 536:       path: {
 537:         type: "string",
 538:         description: "Directory or file to search (default: workspace root)",
 539:       },
 540:       include: {
 541:         type: "string",
 542:         description: "File pattern filter, e.g. '*.ts'",
 543:       },
 544:     },
 545:     required: ["pattern"],
 546:   },
 547:   isReadOnly: true,
 548:   isConcurrencySafe: true,
 549: 
 550:   async call(input, context): Promise<ToolResult> {
 551:     const searchDir = input.path
 552:       ? path.resolve(context.workspaceRoot, input.path)
 553:       : context.workspaceRoot;
 554: 
 555:     // Try ripgrep first, fall back to Node.js
 556:     try {
 557:       let cmd = `rg --line-number --no-heading --color never `;
 558: 
 559:       if (input.include) {
 560:         cmd += `--glob '${input.include}' `;
 561:       }
 562: 
 563:       // Ignore common directories
 564:       cmd += `--glob '!node_modules' --glob '!.git' `;
 565: 
 566:       // Escape the pattern for shell
 567:       const escaped = input.pattern.replace(/'/g, "'\\''");
 568:       cmd += `'${escaped}' '${searchDir}'`;
 569: 
 570:       const { stdout } = await execAsync(cmd, {
 571:         timeout: 30_000,
 572:         maxBuffer: 10 * 1024 * 1024,
 573:       });
 574: 
 575:       const lines = stdout.trim().split("\n").filter(Boolean);
 576:       const MAX_RESULTS = 250;
 577:       const truncated = lines.length > MAX_RESULTS;
 578: 
 579:       if (lines.length === 0) {
 580:         return { content: "No matches found." };
 581:       }
 582: 
 583:       return {
 584:         content: lines.slice(0, MAX_RESULTS).join("\n"),
 585:         truncated,
 586:         metadata: { linesRead: Math.min(lines.length, MAX_RESULTS) },
 587:       };
 588:     } catch (error: any) {
 589:       // rg not found or error — fall back
 590:       if (error.code === 1 && error.stdout === "") {
 591:         return { content: "No matches found." };
 592:       }
 593: 
 594:       try {
 595:         // Fallback: use fast-glob + manual regex search
 596:         const pattern = input.include || "**/*";
 597:         const files = await fg(pattern, {
 598:           cwd: searchDir,
 599:           ignore: ["**/node_modules/**", "**/.git/**"],
 600:           absolute: true,
 601:         });
 602: 
 603:         const results: string[] = [];
 604:         const regex = new RegExp(input.pattern, "gi");
 605: 
 606:         for (const file of files.slice(0, 100)) {
 607:           try {
 608:             const stat = fs.statSync(file);
 609:             if (stat.isDirectory() || stat.size > 1024 * 1024) continue;
 610: 
 611:             const content = fs.readFileSync(file, "utf-8");
 612:             const lines = content.split("\n");
 613:             for (let i = 0; i < lines.length; i++) {
 614:               if (regex.test(lines[i])) {
 615:                 const relPath = path.relative(context.workspaceRoot, file);
 616:                 results.push(`${relPath}:${i + 1}: ${lines[i].trim()}`);
 617:                 regex.lastIndex = 0; // Reset
 618:               }
 619:             }
 620:           } catch {
 621:             // Skip unreadable files
 622:           }
 623:         }
 624: 
 625:         const MAX_RESULTS = 250;
 626:         const truncated = results.length > MAX_RESULTS;
 627: 
 628:         if (results.length === 0) {
 629:           return { content: "No matches found." };
 630:         }
 631: 
 632:         return {
 633:           content: results.slice(0, MAX_RESULTS).join("\n"),
 634:           truncated,
 635:           metadata: { linesRead: Math.min(results.length, MAX_RESULTS) },
 636:         };
 637:       } catch (fallbackError: any) {
 638:         return {
 639:           content: "",
 640:           error: `Error searching: ${fallbackError.message}`,
 641:         };
 642:       }
 643:     }
 644:   },
 645: 
 646:   async checkPermissions(_input, _context) {
 647:     return { allowed: true }; // Read-only
 648:   },
 649: });
