 652: // Helpers
 653: // ============================================================
 654: 
 655: function isBinary(buffer: Buffer): boolean {
 656:   // Check first 8KB for null bytes (common binary indicator)
 657:   const sampleSize = Math.min(buffer.length, 8192);
 658:   for (let i = 0; i < sampleSize; i++) {
 659:     if (buffer[i] === 0) return true;
 660:   }
 661:   return false;
 662: }
 663: 
 664: function formatSize(bytes: number): string {
 665:   if (bytes < 1024) return `${bytes} B`;
 666:   if (bytes < 1024 * 1024) return `${(bytes / 1024).toFixed(1)} KB`;
 667:   return `${(bytes / (1024 * 1024)).toFixed(1)} MB`;
 668: }
 669: 
 670: function generateSimpleDiff(oldStr: string, newStr: string): string {
 671:   const oldLines = oldStr.split("\n");
 672:   const newLines = newStr.split("\n");
 673: 
 674:   let diff = "";
 675:   for (const line of oldLines) {
 676:     if (!newLines.includes(line)) {
 677:       diff += `- ${line}\n`;
 678:     }
 679:   }
 680:   for (const line of newLines) {
 681:     if (!oldLines.includes(line)) {
 682:       diff += `+ ${line}\n`;
 683:     }
 684:   }
 685: 
 686:   return diff || "(whitespace-only change)";
 687: }
