   1: // ============================================================
   2: // Todo Tool — Structured task list management
   3: // ============================================================
   4: // LLM creates/updates a structured task list that the user sees
   5: // rendered as a progress tracker. The LLM sends the FULL list
   6: // each time (complete replacement).
   7: // ============================================================
   8: 
   9: import type { Tool, ToolContext, ToolResult } from "./types.js";
  10: import { createTool } from "./tool-registry.js";
  11: 
  12: // --- Types ---
  13: 
  14: interface TodoItem {
  15:   content: string;
  16:   status: "pending" | "in_progress" | "completed";
  17:   activeForm: string;
  18: }
  19: 
  20: interface TodoInput {
  21:   todos: TodoItem[];
  22:   [key: string]: unknown;
  23: }
  24: 
  25: // Module-level session storage
  26: const sessionTodos: Map<string, TodoItem[]> = new Map();
  27: 
  28: // --- Status Display ---
  29: 
  30: const STATUS_MAP: Record<string, string> = {
  31:   pending: "⏳",
  32:   in_progress: "🔄",
  33:   completed: "✅",
  34: };
  35: 
  36: function formatTodoList(todos: TodoItem[]): string {
  37:   if (todos.length === 0) {
  38:     return "(empty todo list)";
  39:   }
  40: 
  41:   const lines: string[] = [];
  42:   for (const item of todos) {
  43:     const icon = STATUS_MAP[item.status] || "❓";
  44:     lines.push(`${icon} [${item.status}] ${item.content}`);
  45:     if (item.status === "in_progress" && item.activeForm) {
  46:       lines.push(`     → ${item.activeForm}`);
  47:     }
  48:   }
  49:   return lines.join("\n");
  50: }
  51: 
  52: // --- Tool ---
  53: 
  54: export const TodoTool: Tool = createTool<TodoInput>({
  55:   name: "todo",
  56:   description:
  57:     "Create and update a structured task list for the current coding session",
  58:   promptDescription:
  59:     "Create and update a structured task list for your current coding session. " +
  60:     "Send the FULL list as { todos: [...] } each time — any existing items not " +
  61:     "in the new list are removed. Each item needs content (description), status " +
  62:     '(one of "pending" | "in_progress" | "completed"), and activeForm ' +
  63:     "(a present-tense label shown while in progress, e.g. 'Adding tests').",
  64:   inputSchema: {
  65:     type: "object",
  66:     properties: {
  67:       todos: {
  68:         type: "array",
  69:         description:
  70:           "The COMPLETE todo list. Items not included will be removed.",
  71:       },
  72:     },
  73:     required: ["todos"],
  74:   },
  75:   isReadOnly: false,
  76:   isConcurrencySafe: false,
  77: 
  78:   async call(input, context): Promise<ToolResult> {
  79:     const todos = input.todos ?? [];
  80: 
  81:     // Validate
  82:     for (const item of todos) {
  83:       if (!item.content || typeof item.content !== "string") {
  84:         return {
  85:           content: "",
  86:           error: `Invalid todo item: missing "content" (string)`,
  87:         };
  88:       }
  89:       if (
  90:         !["pending", "in_progress", "completed"].includes(item.status)
  91:       ) {
  92:         return {
  93:           content: "",
  94:           error: `Invalid status "${item.status}" for "${item.content}". Must be: pending | in_progress | completed`,
  95:         };
  96:       }
  97:     }
  98: 
  99:     // Store
 100:     sessionTodos.set(context.sessionId, todos);
 101: 
 102:     // Format display
 103:     const counts = {
 104:       pending: 0,
 105:       in_progress: 0,
 106:       completed: 0,
 107:       total: todos.length,
 108:     };
 109:     for (const item of todos) {
 110:       if (item.status === "completed") counts.completed++;
 111:       else if (item.status === "in_progress") counts.in_progress++;
 112:       else counts.pending++;
 113:     }
 114: 
 115:     let content = `Todo list updated: ${counts.total} items`;
 116:     content += ` (${counts.pending} pending, ${counts.in_progress} in progress, ${counts.completed} completed)\n\n`;
 117:     content += formatTodoList(todos);
 118: 
 119:     return {
 120:       content,
 121:       metadata: {
 122:         linesRead: counts.total,
 123:       },
 124:     };
 125:   },
 126: 
 127:   checkPermissions: async (_input, _context) => {
 128:     return { allowed: true }; // Not destructive
 129:   },
 130: });
 131: 
 132: // --- Export helpers ---
 133: 
 134: export function getTodos(sessionId: string): TodoItem[] {
 135:   return sessionTodos.get(sessionId) ?? [];
 136: }
 137: 
 138: export function clearTodos(sessionId: string): void {
 139:   sessionTodos.delete(sessionId);
 140: }
