   1: // ============================================================
   2: // Permission System — 4 modes + dangerous pattern detection
   3: // ============================================================
   4: 
   5: import * as path from "node:path";
   6: import type { Tool, ToolContext, ToolInput } from "./types.js";
   7: 
   8: // --- Dangerous Pattern Detection ---
   9: 
  10: interface DangerousCheck {
  11:   dangerous: boolean;
  12:   reason?: string;
  13: }
  14: 
  15: export function checkDangerousPattern(
  16:   toolName: string,
  17:   input: Record<string, unknown>,
  18:   workspaceRoot: string,
  19: ): DangerousCheck {
  20:   // Workspace boundary check for file operations
  21:   if (input.filePath && typeof input.filePath === "string") {
  22:     const resolved = path.resolve(input.filePath as string);
  23:     const resolvedWorkspace = path.resolve(workspaceRoot);
  24:     if (!resolved.startsWith(resolvedWorkspace + path.sep) && resolved !== resolvedWorkspace) {
  25:       return {
  26:         dangerous: true,
  27:         reason: `Path "${input.filePath}" is outside workspace "${workspaceRoot}"`,
  28:       };
  29:     }
  30:   }
  31: 
  32:   // Bash-specific dangerous patterns
  33:   if (toolName === "bash" && input.command && typeof input.command === "string") {
  34:     const cmd = input.command as string;
  35: 
  36:     // Recursive deletion
  37:     if (/\brm\s+.*-r/.test(cmd) || /\brm\s+.*-rf\b/.test(cmd)) {
  38:       return {
  39:         dangerous: true,
  40:         reason: "Command includes recursive deletion (rm -r)",
  41:       };
  42:     }
  43: 
  44:     // Privilege escalation
  45:     if (/\bsudo\b/.test(cmd)) {
  46:       return {
  47:         dangerous: true,
  48:         reason: "Command uses sudo (privilege escalation)",
  49:       };
  50:     }
  51: 
  52:     // Pipe to shell
  53:     if (/(curl|wget).*\|.*(bash|sh|zsh)/.test(cmd)) {
  54:       return {
  55:         dangerous: true,
  56:         reason: "Command pipes downloaded content to a shell",
  57:       };
  58:     }
  59: 
  60:     // Force push
  61:     if (/\bgit\s+push\s+.*--force/.test(cmd)) {
  62:       return {
  63:         dangerous: true,
  64:         reason: "Force pushing to git",
  65:       };
  66:     }
  67: 
  68:     // Hard reset
  69:     if (/\bgit\s+reset\s+--hard/.test(cmd)) {
  70:       return {
  71:         dangerous: true,
  72:         reason: "Git hard reset — this discards changes",
  73:       };
  74:     }
  75: 
  76:     // Disk/filesystem operations
  77:     if (/\b(mkfs|dd|fdisk)\b/.test(cmd)) {
  78:       return {
  79:         dangerous: true,
  80:         reason: "Command includes disk/filesystem operations",
  81:       };
  82:     }
  83:   }
  84: 
  85:   return { dangerous: false };
  86: }
  87: 
  88: // --- Blocked Paths ---
  89: 
  90: const BLOCKED_PATTERNS = [
  91:   /\.ssh\/.*/,
  92:   /\.ssh$/,
  93:   /\/etc\/(passwd|shadow|sudoers)/,
  94:   /\/etc\/ssl\//,
  95:   /\.env$/,
  96:   /\.env\./,
  97:   /credentials\.json$/,
  98:   /\.npmrc$/,
  99:   /\.git\/config$/,
 100:   /\.git\/hooks\//,
 101: ];
 102: 
 103: export function isBlockedPath(filePath: string): boolean {
 104:   return BLOCKED_PATTERNS.some((pattern) => pattern.test(filePath));
 105: }
 106: 
 107: // --- Main Permission Check ---
 108: 
 109: export interface PermissionCheckOptions {
 110:   /** Callback to prompt the user for permission */
 111:   askUser: (
 112:     tool: Tool,
 113:     input: Record<string, unknown>,
 114:     riskHint?: string,
 115:   ) => Promise<boolean>;
 116: }
 117: 
 118: export async function checkPermission(
 119:   tool: Tool,
 120:   input: Record<string, unknown>,
 121:   context: ToolContext,
 122:   options: PermissionCheckOptions,
 123: ): Promise<{ allowed: boolean; reason?: string }> {
 124:   // Step 1: Read-only tools are always allowed
 125:   if (tool.isReadOnly()) {
 126:     return { allowed: true };
 127:   }
 128: 
 129:   // Step 2: Plan mode — never execute destructive tools
 130:   if (context.permissionMode === "plan") {
 131:     return {
 132:       allowed: false,
 133:       reason: `Plan mode: ${tool.name} is a destructive tool. Not executing.`,
 134:     };
 135:   }
 136: 
 137:   // Step 3: Bypass mode — everything is allowed
 138:   if (context.permissionMode === "bypassPermissions") {
 139:     return { allowed: true };
 140:   }
 141: 
 142:   // Step 4: Check blocked paths
 143:   if (input.filePath && typeof input.filePath === "string") {
 144:     if (isBlockedPath(input.filePath as string)) {
 145:       return {
 146:         allowed: false,
 147:         reason: `Path "${input.filePath}" is blocked for security reasons.`,
 148:       };
 149:     }
 150:   }
 151: 
 152:   // Step 5: Dangerous patterns — ALWAYS require confirmation
 153:   const dangerousCheck = checkDangerousPattern(
 154:     tool.name,
 155:     input,
 156:     context.workspaceRoot,
 157:   );
 158:   if (dangerousCheck.dangerous) {
 159:     const allowed = await options.askUser(tool, input, dangerousCheck.reason);
 160:     return allowed
 161:       ? { allowed: true }
 162:       : { allowed: false, reason: dangerousCheck.reason };
 163:   }
 164: 
 165:   // Step 6: acceptEdits — auto-approve file operations
 166:   if (context.permissionMode === "acceptEdits") {
 167:     if (["edit", "write"].includes(tool.name)) {
 168:       return { allowed: true };
 169:     }
 170:   }
 171: 
 172:   // Step 7: Default — ask for all destructive operations
 173:   const allowed = await options.askUser(tool, input);
 174:   return allowed
 175:     ? { allowed: true }
 176:     : { allowed: false, reason: "User denied permission" };
 177: }
