   1: // ============================================================
   2: // Persistence — Save and restore conversation sessions
   3: // ============================================================
   4: // Stores conversation history as JSON files under
   5: // <workspace>/.claude/sessions/<sessionId>.json
   6: // ============================================================
   7: 
   8: import * as fs from "node:fs";
   9: import * as path from "node:path";
  10: import * as crypto from "node:crypto";
  11: import type { Message } from "./types.js";
  12: 
  13: // --- Types ---
  14: 
  15: export interface SessionData {
  16:   version: number;
  17:   sessionId: string;
  18:   createdAt: string; // ISO 8601
  19:   updatedAt: string; // ISO 8601
  20:   workspaceRoot: string;
  21:   messages: Message[];
  22:   messageCount: number;
  23:   completed: boolean;
  24: }
  25: 
  26: export interface SessionMeta {
  27:   sessionId: string;
  28:   createdAt: string;
  29:   updatedAt: string;
  30:   messageCount: number;
  31:   completed: boolean;
  32: }
  33: 
  34: // --- Persistence Manager ---
  35: 
  36: export class PersistenceManager {
  37:   private sessionsDir: string;
  38: 
  39:   constructor(workspaceRoot: string) {
  40:     this.sessionsDir = path.join(workspaceRoot, ".claude", "sessions");
  41:   }
  42: 
  43:   /**
  44:    * Ensure the sessions directory exists
  45:    */
  46:   private ensureDir(): void {
  47:     fs.mkdirSync(this.sessionsDir, { recursive: true });
  48:   }
  49: 
  50:   /**
  51:    * Get the file path for a session
  52:    */
  53:   private sessionPath(sessionId: string): string {
  54:     return path.join(this.sessionsDir, `${sessionId}.json`);
  55:   }
  56: 
  57:   /**
  58:    * Generate a new session ID
  59:    */
  60:   generateId(): string {
  61:     return crypto.randomUUID();
  62:   }
  63: 
  64:   /**
  65:    * Save a session to disk
  66:    */
  67:   async save(
  68:     sessionId: string,
  69:     messages: Message[],
  70:     options?: { completed?: boolean },
  71:   ): Promise<void> {
  72:     this.ensureDir();
  73: 
  74:     const filePath = this.sessionPath(sessionId);
  75:     const now = new Date().toISOString();
  76: 
  77:     let data: SessionData;
  78: 
  79:     // Try to load existing session to preserve createdAt
  80:     const existing = this.loadSync(sessionId);
  81:     if (existing) {
  82:       data = {
  83:         ...existing,
  84:         updatedAt: now,
  85:         messages,
  86:         messageCount: messages.length,
  87:         completed: options?.completed ?? existing.completed,
  88:       };
  89:     } else {
  90:       data = {
  91:         version: 1,
  92:         sessionId,
  93:         createdAt: now,
  94:         updatedAt: now,
  95:         workspaceRoot: path.dirname(this.sessionsDir),
  96:         messages,
  97:         messageCount: messages.length,
  98:         completed: options?.completed ?? false,
  99:       };
 100:     }
 101: 
 102:     const json = JSON.stringify(data, null, 2);
 103:     fs.writeFileSync(filePath, json, "utf-8");
 104:   }
 105: 
 106:   /**
 107:    * Load a session from disk (async)
 108:    */
 109:   async load(sessionId: string): Promise<SessionData | null> {
 110:     return this.loadSync(sessionId);
 111:   }
 112: 
 113:   /**
 114:    * Load a session synchronously
 115:    */
 116:   private loadSync(sessionId: string): SessionData | null {
 117:     const filePath = this.sessionPath(sessionId);
 118:     try {
 119:       const raw = fs.readFileSync(filePath, "utf-8");
 120:       const data: SessionData = JSON.parse(raw);
 121: 
 122:       // Basic validation
 123:       if (!data.version || !data.sessionId || !Array.isArray(data.messages)) {
 124:         return null;
 125:       }
 126: 
 127:       return data;
 128:     } catch (error: any) {
 129:       if (error.code === "ENOENT") return null;
 130:       throw error;
 131:     }
 132:   }
 133: 
 134:   /**
 135:    * List all available sessions with metadata
 136:    */
 137:   async listSessions(): Promise<SessionMeta[]> {
 138:     this.ensureDir();
 139: 
 140:     try {
 141:       const entries = fs.readdirSync(this.sessionsDir, { withFileTypes: true });
 142:       const sessions: SessionMeta[] = [];
 143: 
 144:       for (const entry of entries) {
 145:         if (!entry.isFile() || !entry.name.endsWith(".json")) continue;
 146: 
 147:         const sessionId = entry.name.replace(/\.json$/, "");
 148:         const data = this.loadSync(sessionId);
 149:         if (!data) continue;
 150: 
 151:         sessions.push({
 152:           sessionId: data.sessionId,
 153:           createdAt: data.createdAt,
 154:           updatedAt: data.updatedAt,
 155:           messageCount: data.messageCount,
 156:           completed: data.completed,
 157:         });
 158:       }
 159: 
 160:       // Sort by most recently updated first
 161:       sessions.sort(
 162:         (a, b) =>
 163:           new Date(b.updatedAt).getTime() - new Date(a.updatedAt).getTime(),
 164:       );
 165: 
 166:       return sessions;
 167:     } catch {
 168:       return [];
 169:     }
 170:   }
 171: 
 172:   /**
 173:    * Delete a session
 174:    */
 175:   async deleteSession(sessionId: string): Promise<void> {
 176:     const filePath = this.sessionPath(sessionId);
 177:     try {
