   1: // ============================================================
   2: // MCP (Model Context Protocol) Integration
   3: // ============================================================
   4: // Connects to external MCP servers (stdio/http/sse), discovers
   5: // their tools, and wraps them as native Tool objects for the
   6: // agent loop. Uses the official @modelcontextprotocol/sdk.
   7: // ============================================================
   8: 
   9: import * as fs from "node:fs";
  10: import * as path from "node:path";
  11: import * as os from "node:os";
  12: import { Client } from "@modelcontextprotocol/sdk/client/index.js";
  13: import { StdioClientTransport } from "@modelcontextprotocol/sdk/client/stdio.js";
  14: import { StreamableHTTPClientTransport } from "@modelcontextprotocol/sdk/client/streamableHttp.js";
  15: import type { Tool, ToolResult } from "./types.js";
  16: 
  17: // --- MCP Server Config ---
  18: 
  19: export interface MCPServerConfig {
  20:   type: "stdio" | "http" | "sse";
  21:   command?: string;
  22:   args?: string[];
  23:   env?: Record<string, string>;
  24:   url?: string;
  25:   headers?: Record<string, string>;
  26:   disabled?: boolean;
  27: }
  28: 
  29: export interface MCPConfig {
  30:   mcpServers: Record<string, MCPServerConfig>;
  31: }
  32: 
  33: // --- Server entry ---
  34: 
  35: interface ServerEntry {
  36:   config: MCPServerConfig;
  37:   client: Client;
  38:   tools: Tool[];
  39: }
  40: 
  41: // --- MCP Manager ---
  42: 
  43: export class MCPManager {
  44:   private servers: Map<string, ServerEntry> = new Map();
  45: 
  46:   /**
  47:    * Load MCP configuration from a JSON file
  48:    */
  49:   async loadConfig(configPath: string): Promise<void> {
  50:     let raw: string;
  51:     try {
  52:       raw = fs.readFileSync(configPath, "utf-8");
  53:     } catch (error: any) {
  54:       if (error.code === "ENOENT") return; // Config file doesn't exist — fine
  55:       console.error(
  56:         `Error reading MCP config from ${configPath}:`,
  57:         error.message,
  58:       );
  59:       return;
  60:     }
  61: 
  62:     let config: MCPConfig;
  63:     try {
  64:       config = JSON.parse(raw);
  65:     } catch (error: any) {
  66:       console.error(
  67:         `Error parsing MCP config from ${configPath}:`,
  68:         error.message,
  69:       );
  70:       return;
  71:     }
  72: 
  73:     for (const [name, serverConfig] of Object.entries(config.mcpServers)) {
  74:       if (serverConfig.disabled) continue;
  75:       await this.connectServer(name, serverConfig);
  76:     }
  77:   }
  78: 
  79:   /**
  80:    * Connect to a single MCP server and discover its tools
  81:    */
  82:   async connectServer(
  83:     name: string,
  84:     config: MCPServerConfig,
  85:   ): Promise<void> {
  86:     // Don't double-connect
  87:     if (this.servers.has(name)) {
  88:       console.warn(`MCP server "${name}" is already connected.`);
  89:       return;
  90:     }
  91: 
  92:     let client: Client;
  93: 
  94:     try {
  95:       // --- Create transport based on type ---
  96:       if (config.type === "stdio") {
  97:         if (!config.command) {
  98:           console.error(
  99:             `MCP server "${name}": stdio transport requires a "command"`,
 100:           );
 101:           return;
 102:         }
 103:         const transport = new StdioClientTransport({
 104:           command: config.command,
 105:           args: config.args || [],
 106:           env: { ...process.env, ...(config.env || {}) } as Record<string, string>,
 107:         });
 108:         client = new Client(
 109:           { name: "claude-code-replica", version: "1.0.0" },
 110:           { capabilities: {} as any },
 111:         );
 112:         await client.connect(transport);
 113:       } else if (config.type === "http" || config.type === "sse") {
 114:         if (!config.url) {
 115:           console.error(
 116:             `MCP server "${name}": ${config.type} transport requires a "url"`,
 117:           );
 118:           return;
 119:         }
 120:         const transport = new StreamableHTTPClientTransport(
 121:           new URL(config.url),
 122:           { requestInit: config.headers ? { headers: config.headers } : {} },
 123:         );
 124:         client = new Client(
 125:           { name: "claude-code-replica", version: "1.0.0" },
 126:           { capabilities: {} as any },
 127:         );
 128:         await client.connect(transport);
 129:       } else {
 130:         console.error(
 131:           `MCP server "${name}": unknown transport type "${(config as any).type}"`,
 132:         );
 133:         return;
 134:       }
 135: 
 136:       // --- Discover tools ---
 137:       const toolsResult = await client.listTools();
 138:       const mcpTools: Tool[] = toolsResult.tools.map(
 139:         (remoteTool: any) => {
 140:           // Build input schema, ensuring it's a valid JSON Schema object
 141:           const rawSchema = remoteTool.inputSchema || {};
 142:           const inputSchema: Tool["inputSchema"] = {
 143:             type: "object",
 144:             properties:
 145:               rawSchema.properties &&
 146:               typeof rawSchema.properties === "object"
 147:                 ? rawSchema.properties
 148:                 : {},
 149:             required: Array.isArray(rawSchema.required)
 150:               ? rawSchema.required
 151:               : [],
 152:           };
 153: 
 154:           const toolName = `mcp__${name}__${remoteTool.name}`;
 155: 
 156:           return {
 157:             name: toolName,
 158:             description: `MCP tool: ${remoteTool.name} (from ${name} server)`,
 159:             promptDescription:
 160:               remoteTool.description ||
 161:               `MCP tool "${remoteTool.name}" from server "${name}"`,
 162:             inputSchema,
 163:             isEnabled: () => true,
 164:             isReadOnly: () => false, // Conservative — assume destructive
 165:             isConcurrencySafe: () => true, // Separate process, safe to run in parallel
 166: 
 167:             async call(input: Record<string, unknown>): Promise<ToolResult> {
 168:               try {
 169:                 const result = await client.callTool({
 170:                   name: remoteTool.name,
 171:                   arguments: input,
 172:                 });
 173: 
 174:                 // Extract text content from result
 175:                 const content = (result.content as any[])
 176:                   .filter((c: any) => c.type === "text")
 177:                   .map((c: any) => c.text)
 178:                   .join("\n");
 179: 
 180:                 return { content: content || "(no text output)" };
 181:               } catch (error: any) {
 182:                 return {
 183:                   content: "",
 184:                   error: `MCP tool error (${toolName}): ${error.message}`,
 185:                 };
 186:               }
 187:             },
 188: 
 189:             formatResult: (r: ToolResult) => {
 190:               if (r.error) return `Error: ${r.error}`;
 191:               return r.content;
 192:             },
 193: 
 194:             checkPermissions: async () => ({ allowed: true }),
 195:             // MCP tools auto-approved — user trusted the server
 196:           } as Tool;
 197:         },
 198:       );
 199: 
 200:       this.servers.set(name, { config, client, tools: mcpTools });
 201:       console.log(
 202:         `MCP server "${name}" connected (${config.type}) — ${mcpTools.length} tool(s)`,
 203:       );
 204:     } catch (error: any) {
 205:       console.error(
 206:         `Failed to connect MCP server "${name}": ${error.message}`,
 207:       );
 208:       // Don't crash — MCP is optional
 209:     }
 210:   }
 211: 
 212:   /**
 213:    * Get all tools from connected MCP servers
 214:    */
 215:   getAllTools(): Tool[] {
 216:     const allTools: Tool[] = [];
 217:     for (const [, server] of this.servers) {
 218:       allTools.push(...server.tools);
 219:     }
 220:     return allTools;
 221:   }
 222: 
 223:   /**
 224:    * Disconnect all MCP servers
 225:    */
 226:   async disconnectAll(): Promise<void> {
 227:     for (const [name, server] of this.servers) {
 228:       try {
 229:         await server.client.close();
 230:         console.log(`MCP server "${name}" disconnected.`);
 231:       } catch (error: any) {
 232:         console.error(
 233:           `Error disconnecting MCP server "${name}": ${error.message}`,
 234:         );
 235:       }
 236:     }
 237:     this.servers.clear();
 238:   }
 239: 
 240:   /**
 241:    * Disconnect a single server by name
 242:    */
 243:   async disconnectServer(name: string): Promise<void> {
 244:     const server = this.servers.get(name);
 245:     if (!server) return;
 246:     try {
 247:       await server.client.close();
 248:     } catch (error: any) {
 249:       console.error(
 250:         `Error disconnecting MCP server "${name}": ${error.message}`,
 251:       );
 252:     }
 253:     this.servers.delete(name);
 254:   }
 255: 
 256:   /**
 257:    * Get the number of connected servers
 258:    */
 259:   get serverCount(): number {
 260:     return this.servers.size;
 261:   }
 262: }
 263: 
 264: // --- Discover MCP Config Files ---
 265: 
 266: /**
 267:  * Find all MCP configuration files from standard locations
 268:  */
 269: export function discoverMCPConfigs(workspaceRoot: string): string[] {
 270:   const configs: string[] = [];
 271: 
 272:   // User-level config (~/.claude/mcp.json)
 273:   const userConfig = path.join(os.homedir(), ".claude", "mcp.json");
 274:   if (fs.existsSync(userConfig)) {
 275:     configs.push(userConfig);
 276:   }
 277: 
 278:   // Project-level config (<workspace>/.mcp.json)
 279:   const projectConfig = path.join(workspaceRoot, ".mcp.json");
 280:   if (fs.existsSync(projectConfig)) {
 281:     configs.push(projectConfig);
 282:   }
 283: 
 284:   return configs;
 285: }
